-- TMDB-MOVIE-PREPROCESS-071, check of the queries Process 44 will run (2026-11-10).
-- Read only: SELECT and EXPLAIN. Voie 1:
--   ssh vps-agent pull tmdb-movie-preprocess
--   ssh vps-agent run tmdb-movie-preprocess/doc/sql/check-071-win-query.sql
--
-- GENERATED from the helpers themselves (f_awardwinsql, f_awardfamilysql and the lookup
-- constants of tmdb_preprocess_helpers.py), the %s bound to literals: what is checked
-- here is the SQL the nightly run executes, not a copy written by hand. It settles,
-- before the first build: that each query parses, its plan, and its answer on the
-- cases the evaluations assert (Katharine Hepburn's four Oscars for Best Actress,
-- the Cesar for Best Film of 2010).
-- Safe to pull before the migration: Process 44 skips itself while the columns of
-- migration-071-award-wins.sql are missing (section A lists the ones present).

SELECT '=== A. the -071 columns present today (none before the migration, twelve after) ===' AS section;

SELECT TABLE_NAME, COLUMN_NAME FROM information_schema.COLUMNS WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME IN ('T_WC_T2S_MOVIE_AWARD', 'T_WC_T2S_SERIE_AWARD', 'T_WC_T2S_PERSON_AWARD', 'T_WC_T2S_AWARD')
  AND COLUMN_NAME IN ('ID_STATEMENT', 'AWARD_YEAR', 'ID_CEREMONY_WIKIDATA', 'ID_MOVIE_FOR', 'ID_SERIE_FOR', 'ID_AWARD_PARENT')
ORDER BY TABLE_NAME, ORDINAL_POSITION;

SELECT '=== B. plan of the win query: persons, Academy Award for Best Actress (Q103618) ===' AS section;

EXPLAIN SELECT p2.ID_PERSON, p2.POPULARITY, sl.ID_STATEMENT, q.ID_QUALIFIER_PROPERTY, qt.YEAR_VALUE, qi.ID_ITEM AS ID_QUALIFIER_ITEM FROM T_WC_WIKIDATA_ITEM_VALUE lv JOIN T_WC_WIKIDATA_STATEMENT sl ON sl.ID_STATEMENT = lv.ID_STATEMENT STRAIGHT_JOIN T_WC_T2S_PERSON p2 ON p2.ID_WIKIDATA = sl.ID_WIKIDATA LEFT JOIN T_WC_WIKIDATA_STATEMENT_QUALIFIER q ON q.ID_STATEMENT = sl.ID_STATEMENT AND q.ID_QUALIFIER_PROPERTY IN ('P585', 'P1686', 'P805') LEFT JOIN T_WC_WIKIDATA_QUALIFIER_TIME_VALUE qt ON qt.ID_STATEMENT_QUALIFIER = q.ID_STATEMENT_QUALIFIER LEFT JOIN T_WC_WIKIDATA_QUALIFIER_ITEM_VALUE qi ON qi.ID_STATEMENT_QUALIFIER = q.ID_STATEMENT_QUALIFIER WHERE sl.ID_PROPERTY = 'P166' AND lv.ID_ITEM = 'Q103618' AND (sl.`RANK` IS NULL OR sl.`RANK` <> 'deprecated') AND p2.ID_WIKIDATA IS NOT NULL AND p2.ID_WIKIDATA <> '' ORDER BY p2.POPULARITY DESC, p2.ID_PERSON ASC, sl.ID_STATEMENT ASC;

SELECT '=== C. its size: lines, statements, persons ===' AS section;

SELECT COUNT(*) AS QUERY_LINES, COUNT(DISTINCT x.ID_STATEMENT) AS STATEMENTS, COUNT(DISTINCT x.ID_PERSON) AS PERSONS
FROM (SELECT p2.ID_PERSON, p2.POPULARITY, sl.ID_STATEMENT, q.ID_QUALIFIER_PROPERTY, qt.YEAR_VALUE, qi.ID_ITEM AS ID_QUALIFIER_ITEM FROM T_WC_WIKIDATA_ITEM_VALUE lv JOIN T_WC_WIKIDATA_STATEMENT sl ON sl.ID_STATEMENT = lv.ID_STATEMENT STRAIGHT_JOIN T_WC_T2S_PERSON p2 ON p2.ID_WIKIDATA = sl.ID_WIKIDATA LEFT JOIN T_WC_WIKIDATA_STATEMENT_QUALIFIER q ON q.ID_STATEMENT = sl.ID_STATEMENT AND q.ID_QUALIFIER_PROPERTY IN ('P585', 'P1686', 'P805') LEFT JOIN T_WC_WIKIDATA_QUALIFIER_TIME_VALUE qt ON qt.ID_STATEMENT_QUALIFIER = q.ID_STATEMENT_QUALIFIER LEFT JOIN T_WC_WIKIDATA_QUALIFIER_ITEM_VALUE qi ON qi.ID_STATEMENT_QUALIFIER = q.ID_STATEMENT_QUALIFIER WHERE sl.ID_PROPERTY = 'P166' AND lv.ID_ITEM = 'Q103618' AND (sl.`RANK` IS NULL OR sl.`RANK` <> 'deprecated') AND p2.ID_WIKIDATA IS NOT NULL AND p2.ID_WIKIDATA <> '' ORDER BY p2.POPULARITY DESC, p2.ID_PERSON ASC, sl.ID_STATEMENT ASC) x;

SELECT '=== D. Katharine Hepburn (6598): four statements expected, years 1934, 1968, 1969, 1982, one work each ===' AS section;

SELECT x.* FROM (SELECT p2.ID_PERSON, p2.POPULARITY, sl.ID_STATEMENT, q.ID_QUALIFIER_PROPERTY, qt.YEAR_VALUE, qi.ID_ITEM AS ID_QUALIFIER_ITEM FROM T_WC_WIKIDATA_ITEM_VALUE lv JOIN T_WC_WIKIDATA_STATEMENT sl ON sl.ID_STATEMENT = lv.ID_STATEMENT STRAIGHT_JOIN T_WC_T2S_PERSON p2 ON p2.ID_WIKIDATA = sl.ID_WIKIDATA LEFT JOIN T_WC_WIKIDATA_STATEMENT_QUALIFIER q ON q.ID_STATEMENT = sl.ID_STATEMENT AND q.ID_QUALIFIER_PROPERTY IN ('P585', 'P1686', 'P805') LEFT JOIN T_WC_WIKIDATA_QUALIFIER_TIME_VALUE qt ON qt.ID_STATEMENT_QUALIFIER = q.ID_STATEMENT_QUALIFIER LEFT JOIN T_WC_WIKIDATA_QUALIFIER_ITEM_VALUE qi ON qi.ID_STATEMENT_QUALIFIER = q.ID_STATEMENT_QUALIFIER WHERE sl.ID_PROPERTY = 'P166' AND lv.ID_ITEM = 'Q103618' AND (sl.`RANK` IS NULL OR sl.`RANK` <> 'deprecated') AND p2.ID_WIKIDATA IS NOT NULL AND p2.ID_WIKIDATA <> '' ORDER BY p2.POPULARITY DESC, p2.ID_PERSON ASC, sl.ID_STATEMENT ASC) x WHERE x.ID_PERSON = 6598 ORDER BY x.ID_STATEMENT, x.ID_QUALIFIER_PROPERTY;

SELECT '=== E. the works of those four wins, resolved as Process 44 resolves them ===' AS section;

SELECT ID_WIKIDATA, ID_MOVIE FROM T_WC_T2S_MOVIE WHERE ID_WIKIDATA IN ('Q572789', 'Q736969', 'Q1195311', 'Q451603') ORDER BY ID_WIKIDATA, ID_MOVIE;

SELECT '=== F. movies, Cesar Award for Best Film (Q645595): the lines of 2010 (A Prophet, 21575) ===' AS section;

SELECT x.* FROM (SELECT m.ID_MOVIE, m.IMDB_RATING_WEIGHTED, sl.ID_STATEMENT, q.ID_QUALIFIER_PROPERTY, qt.YEAR_VALUE, qi.ID_ITEM AS ID_QUALIFIER_ITEM FROM T_WC_WIKIDATA_ITEM_VALUE lv JOIN T_WC_WIKIDATA_STATEMENT sl ON sl.ID_STATEMENT = lv.ID_STATEMENT STRAIGHT_JOIN T_WC_T2S_MOVIE m ON m.ID_WIKIDATA = sl.ID_WIKIDATA LEFT JOIN T_WC_WIKIDATA_STATEMENT_QUALIFIER q ON q.ID_STATEMENT = sl.ID_STATEMENT AND q.ID_QUALIFIER_PROPERTY IN ('P585', 'P1686', 'P805') LEFT JOIN T_WC_WIKIDATA_QUALIFIER_TIME_VALUE qt ON qt.ID_STATEMENT_QUALIFIER = q.ID_STATEMENT_QUALIFIER LEFT JOIN T_WC_WIKIDATA_QUALIFIER_ITEM_VALUE qi ON qi.ID_STATEMENT_QUALIFIER = q.ID_STATEMENT_QUALIFIER WHERE sl.ID_PROPERTY = 'P166' AND lv.ID_ITEM = 'Q645595' AND (sl.`RANK` IS NULL OR sl.`RANK` <> 'deprecated') AND m.ID_WIKIDATA IS NOT NULL AND m.ID_WIKIDATA <> '' ORDER BY m.IMDB_RATING_WEIGHTED DESC, m.ID_MOVIE ASC, sl.ID_STATEMENT ASC) x WHERE x.YEAR_VALUE = 2010 ORDER BY x.ID_MOVIE, x.ID_STATEMENT;

SELECT '=== G. the year of the ceremonies quoted by the Best Actress wins (ceremony lookup) ===' AS section;

SELECT cs.ID_WIKIDATA, ct.YEAR_VALUE FROM T_WC_WIKIDATA_STATEMENT cs JOIN T_WC_WIKIDATA_TIME_VALUE ct ON ct.ID_STATEMENT = cs.ID_STATEMENT WHERE cs.ID_PROPERTY = 'P585' AND (cs.`RANK` IS NULL OR cs.`RANK` <> 'deprecated') AND cs.ID_WIKIDATA IN (SELECT qi.ID_ITEM FROM T_WC_WIKIDATA_ITEM_VALUE lv
  JOIN T_WC_WIKIDATA_STATEMENT sl ON sl.ID_STATEMENT = lv.ID_STATEMENT AND sl.ID_PROPERTY = 'P166'
  JOIN T_WC_WIKIDATA_STATEMENT_QUALIFIER q ON q.ID_STATEMENT = sl.ID_STATEMENT AND q.ID_QUALIFIER_PROPERTY = 'P805'
  JOIN T_WC_WIKIDATA_QUALIFIER_ITEM_VALUE qi ON qi.ID_STATEMENT_QUALIFIER = q.ID_STATEMENT_QUALIFIER
  WHERE lv.ID_ITEM = 'Q103618') ORDER BY ct.YEAR_VALUE, cs.ID_WIKIDATA;

SELECT '=== H. family route P31: plan, size, and the categories it gives the Academy Awards (Q19020) ===' AS section;

EXPLAIN SELECT c.ID_AWARD, f.ID_AWARD AS ID_AWARD_FAMILY, f.ID_WIKIDATA AS ID_FAMILY_WIKIDATA, 'P31' AS ROUTE FROM T_WC_T2S_AWARD c JOIN T_WC_WIKIDATA_STATEMENT ls ON ls.ID_WIKIDATA = c.ID_WIKIDATA AND ls.ID_PROPERTY = 'P31' AND (ls.`RANK` IS NULL OR ls.`RANK` <> 'deprecated') JOIN T_WC_WIKIDATA_ITEM_VALUE lv ON lv.ID_STATEMENT = ls.ID_STATEMENT JOIN T_WC_T2S_AWARD f ON f.ID_WIKIDATA = lv.ID_ITEM AND f.AWARD_SOURCE = 'P166' AND f.ID_AWARD <> c.ID_AWARD WHERE c.AWARD_SOURCE = 'P166' AND EXISTS (SELECT 1 FROM T_WC_WIKIDATA_STATEMENT gs JOIN T_WC_WIKIDATA_ITEM_VALUE gv ON gv.ID_STATEMENT = gs.ID_STATEMENT WHERE gs.ID_WIKIDATA = f.ID_WIKIDATA AND gs.ID_PROPERTY = 'P31' AND gv.ID_ITEM = 'Q107655869' AND (gs.`RANK` IS NULL OR gs.`RANK` <> 'deprecated'));

SELECT x.ROUTE, COUNT(*) AS PAIRS, COUNT(DISTINCT x.ID_AWARD) AS CATEGORIES, COUNT(DISTINCT x.ID_AWARD_FAMILY) AS FAMILIES
FROM (SELECT c.ID_AWARD, f.ID_AWARD AS ID_AWARD_FAMILY, f.ID_WIKIDATA AS ID_FAMILY_WIKIDATA, 'P31' AS ROUTE FROM T_WC_T2S_AWARD c JOIN T_WC_WIKIDATA_STATEMENT ls ON ls.ID_WIKIDATA = c.ID_WIKIDATA AND ls.ID_PROPERTY = 'P31' AND (ls.`RANK` IS NULL OR ls.`RANK` <> 'deprecated') JOIN T_WC_WIKIDATA_ITEM_VALUE lv ON lv.ID_STATEMENT = ls.ID_STATEMENT JOIN T_WC_T2S_AWARD f ON f.ID_WIKIDATA = lv.ID_ITEM AND f.AWARD_SOURCE = 'P166' AND f.ID_AWARD <> c.ID_AWARD WHERE c.AWARD_SOURCE = 'P166' AND EXISTS (SELECT 1 FROM T_WC_WIKIDATA_STATEMENT gs JOIN T_WC_WIKIDATA_ITEM_VALUE gv ON gv.ID_STATEMENT = gs.ID_STATEMENT WHERE gs.ID_WIKIDATA = f.ID_WIKIDATA AND gs.ID_PROPERTY = 'P31' AND gv.ID_ITEM = 'Q107655869' AND (gs.`RANK` IS NULL OR gs.`RANK` <> 'deprecated'))) x GROUP BY x.ROUTE;

SELECT x.ROUTE, x.ID_AWARD_FAMILY, x.ID_AWARD, a.ID_WIKIDATA, a.AWARD_NAME
FROM (SELECT c.ID_AWARD, f.ID_AWARD AS ID_AWARD_FAMILY, f.ID_WIKIDATA AS ID_FAMILY_WIKIDATA, 'P31' AS ROUTE FROM T_WC_T2S_AWARD c JOIN T_WC_WIKIDATA_STATEMENT ls ON ls.ID_WIKIDATA = c.ID_WIKIDATA AND ls.ID_PROPERTY = 'P31' AND (ls.`RANK` IS NULL OR ls.`RANK` <> 'deprecated') JOIN T_WC_WIKIDATA_ITEM_VALUE lv ON lv.ID_STATEMENT = ls.ID_STATEMENT JOIN T_WC_T2S_AWARD f ON f.ID_WIKIDATA = lv.ID_ITEM AND f.AWARD_SOURCE = 'P166' AND f.ID_AWARD <> c.ID_AWARD WHERE c.AWARD_SOURCE = 'P166' AND EXISTS (SELECT 1 FROM T_WC_WIKIDATA_STATEMENT gs JOIN T_WC_WIKIDATA_ITEM_VALUE gv ON gv.ID_STATEMENT = gs.ID_STATEMENT WHERE gs.ID_WIKIDATA = f.ID_WIKIDATA AND gs.ID_PROPERTY = 'P31' AND gv.ID_ITEM = 'Q107655869' AND (gs.`RANK` IS NULL OR gs.`RANK` <> 'deprecated'))) x JOIN T_WC_T2S_AWARD a ON a.ID_AWARD = x.ID_AWARD
WHERE x.ID_FAMILY_WIKIDATA = 'Q19020' ORDER BY a.AWARD_NAME;

SELECT '=== H. family route P361: plan, size, and the categories it gives the Academy Awards (Q19020) ===' AS section;

EXPLAIN SELECT c.ID_AWARD, f.ID_AWARD AS ID_AWARD_FAMILY, f.ID_WIKIDATA AS ID_FAMILY_WIKIDATA, 'P361' AS ROUTE FROM T_WC_T2S_AWARD c JOIN T_WC_WIKIDATA_STATEMENT ls ON ls.ID_WIKIDATA = c.ID_WIKIDATA AND ls.ID_PROPERTY = 'P361' AND (ls.`RANK` IS NULL OR ls.`RANK` <> 'deprecated') JOIN T_WC_WIKIDATA_ITEM_VALUE lv ON lv.ID_STATEMENT = ls.ID_STATEMENT JOIN T_WC_T2S_AWARD f ON f.ID_WIKIDATA = lv.ID_ITEM AND f.AWARD_SOURCE = 'P166' AND f.ID_AWARD <> c.ID_AWARD WHERE c.AWARD_SOURCE = 'P166' AND EXISTS (SELECT 1 FROM T_WC_WIKIDATA_STATEMENT gs JOIN T_WC_WIKIDATA_ITEM_VALUE gv ON gv.ID_STATEMENT = gs.ID_STATEMENT WHERE gs.ID_WIKIDATA = f.ID_WIKIDATA AND gs.ID_PROPERTY = 'P31' AND gv.ID_ITEM = 'Q107655869' AND (gs.`RANK` IS NULL OR gs.`RANK` <> 'deprecated'));

SELECT x.ROUTE, COUNT(*) AS PAIRS, COUNT(DISTINCT x.ID_AWARD) AS CATEGORIES, COUNT(DISTINCT x.ID_AWARD_FAMILY) AS FAMILIES
FROM (SELECT c.ID_AWARD, f.ID_AWARD AS ID_AWARD_FAMILY, f.ID_WIKIDATA AS ID_FAMILY_WIKIDATA, 'P361' AS ROUTE FROM T_WC_T2S_AWARD c JOIN T_WC_WIKIDATA_STATEMENT ls ON ls.ID_WIKIDATA = c.ID_WIKIDATA AND ls.ID_PROPERTY = 'P361' AND (ls.`RANK` IS NULL OR ls.`RANK` <> 'deprecated') JOIN T_WC_WIKIDATA_ITEM_VALUE lv ON lv.ID_STATEMENT = ls.ID_STATEMENT JOIN T_WC_T2S_AWARD f ON f.ID_WIKIDATA = lv.ID_ITEM AND f.AWARD_SOURCE = 'P166' AND f.ID_AWARD <> c.ID_AWARD WHERE c.AWARD_SOURCE = 'P166' AND EXISTS (SELECT 1 FROM T_WC_WIKIDATA_STATEMENT gs JOIN T_WC_WIKIDATA_ITEM_VALUE gv ON gv.ID_STATEMENT = gs.ID_STATEMENT WHERE gs.ID_WIKIDATA = f.ID_WIKIDATA AND gs.ID_PROPERTY = 'P31' AND gv.ID_ITEM = 'Q107655869' AND (gs.`RANK` IS NULL OR gs.`RANK` <> 'deprecated'))) x GROUP BY x.ROUTE;

SELECT x.ROUTE, x.ID_AWARD_FAMILY, x.ID_AWARD, a.ID_WIKIDATA, a.AWARD_NAME
FROM (SELECT c.ID_AWARD, f.ID_AWARD AS ID_AWARD_FAMILY, f.ID_WIKIDATA AS ID_FAMILY_WIKIDATA, 'P361' AS ROUTE FROM T_WC_T2S_AWARD c JOIN T_WC_WIKIDATA_STATEMENT ls ON ls.ID_WIKIDATA = c.ID_WIKIDATA AND ls.ID_PROPERTY = 'P361' AND (ls.`RANK` IS NULL OR ls.`RANK` <> 'deprecated') JOIN T_WC_WIKIDATA_ITEM_VALUE lv ON lv.ID_STATEMENT = ls.ID_STATEMENT JOIN T_WC_T2S_AWARD f ON f.ID_WIKIDATA = lv.ID_ITEM AND f.AWARD_SOURCE = 'P166' AND f.ID_AWARD <> c.ID_AWARD WHERE c.AWARD_SOURCE = 'P166' AND EXISTS (SELECT 1 FROM T_WC_WIKIDATA_STATEMENT gs JOIN T_WC_WIKIDATA_ITEM_VALUE gv ON gv.ID_STATEMENT = gs.ID_STATEMENT WHERE gs.ID_WIKIDATA = f.ID_WIKIDATA AND gs.ID_PROPERTY = 'P31' AND gv.ID_ITEM = 'Q107655869' AND (gs.`RANK` IS NULL OR gs.`RANK` <> 'deprecated'))) x JOIN T_WC_T2S_AWARD a ON a.ID_AWARD = x.ID_AWARD
WHERE x.ID_FAMILY_WIKIDATA = 'Q19020' ORDER BY a.AWARD_NAME;

