FROM (SELECT c.ID_AWARD, f.ID_AWARD AS ID_AWARD_FAMILY, f.ID_WIKIDATA AS ID_FAMILY_WIKIDATA, 'P527' AS ROUTE FROM T_WC_T2S_AWARD f JOIN T_WC_WIKIDATA_STATEMENT ls ON ls.ID_WIKIDATA = f.ID_WIKIDATA AND ls.ID_PROPERTY = 'P527' AND (ls.`RANK` IS NULL OR ls.`RANK` <> 'deprecated') JOIN T_WC_WIKIDATA_ITEM_VALUE lv ON lv.ID_STATEMENT = ls.ID_STATEMENT JOIN T_WC_T2S_AWARD c ON c.ID_WIKIDATA = lv.ID_ITEM AND c.AWARD_SOURCE = 'P166' AND c.ID_AWARD <> f.ID_AWARD WHERE f.AWARD_SOURCE = 'P166' AND EXISTS (SELECT 1 FROM T_WC_WIKIDATA_STATEMENT gs JOIN T_WC_WIKIDATA_ITEM_VALUE gv ON gv.ID_STATEMENT = gs.ID_STATEMENT WHERE gs.ID_WIKIDATA = f.ID_WIKIDATA AND gs.ID_PROPERTY = 'P31' AND gv.ID_ITEM = 'Q107655869' AND (gs.`RANK` IS NULL OR gs.`RANK` <> 'deprecated'))) x JOIN T_WC_T2S_AWARD a ON a.ID_AWARD = x.ID_AWARD
