SELECT '=== I. French names: Best Actress (269) and the row the French question resolved to on 2026-11-10 ===' AS section;

SELECT ID_AWARD, ID_WIKIDATA, AWARD_NAME, AWARD_NAME_FR, PERSON_COUNT FROM T_WC_T2S_AWARD
WHERE ID_AWARD = 269 OR AWARD_NAME_FR LIKE '%de la meilleure actrice' ORDER BY PERSON_COUNT DESC LIMIT 30;
